    try container.encode(more, forKey: .more)
    try container.encodeIfPresent(calendar, forKey: .calendar)
    try container.encodeIfPresent(unavailable, forKey: .unavailable)
  }
}

public struct CoreCatalogRevision: Codable, Hashable, Sendable {
  public var revision: String
  public init(revision: String) {
    self.revision = revision
  }
  private enum CodingKeys: String, CodingKey {
    case revision
  }
  public init(from decoder: Decoder) throws {
    let container = try decoder.container(keyedBy: CodingKeys.self)
    revision = try container.decode(String.self, forKey: .revision)
  }
  public func encode(to encoder: Encoder) throws {
    var container = encoder.container(keyedBy: CodingKeys.self)
    try container.encode(revision, forKey: .revision)
  }
}

